\label{thm:Local} 
Assume that $\bm{F}\in C^0(\mathbb{R}^{n_{X}+8}\times[0,1];\mathbb{R}^{n_{X}})$ and $\bm{G} \in C^0(\mathbb{R}^{n_{X}+8}\times[0,1];\mathbb{R}^8)$ are locally Lipschitz with respect to $(\bm{X},\bm{w})$, uniformly with respect to $z\in[0,1]$, and that the boundary map $\bm{H}\in C^0(\mathbb{R}^{8+n_U};\mathbb{R}^8)$ satisfies the global Lipschitz condition
\begin{align}\label{eq:globalHLips}
\begin{split}
& \norm{\bm{H}(\bm{a}_1,\bm{b}_1,\bm{U})-\bm{H}(\bm{a}_2,\bm{b}_2,\bm{U})}_{\ell^1(\mathbb{R}^8)} \leq L_H\norm{(\bm{a}_1-\bm{a}_2,\bm{b_1}-\bm{b}_2)}_{\ell^1(\mathbb{R}^8)},\quad  (\bm{a}_1,\bm{a}_2,\bm{b_1},\bm{b_2},\bm{U}) \in \mathbb{R}^{16+n_U},
\end{split}
\end{align}
for some $L_H \in \mathbb{R}_{\geq 0}$, and 
\begin{align}\label{eq:h_0bound}
\sup_{t\in\mathbb{R}_{\geq 0}}\norm{\bm{h}_0(t)}_{\ell^1(\mathbb{R}^8)} \triangleq \sup_{t\in\mathbb{R}_{\geq 0}}\norm{\bm{H}(\bm{0},\bm{0},\bm{U}(t))}_{\ell^1(\mathbb{R}^8)}= M_H < \infty.
\end{align}
Then, for every input $\bm{U}\in C^0(\mathbb{R}_{\geq 0};\mathbb{R}^{n_U})$ and \emph{initial condition} (IC) $ (\bm{X}_0,\bm{w}_0^+,\bm{w}_0^-)  = (\bm{X}_0,\bm{w}_0)\triangleq (\bm{X}(\cdot,0),\bm{w}(\cdot,0)) \in C^0([0,1];\mathbb{R}^{n_{X}+8})$ satisfying the zeroth-order compatibility condition
\begin{align}
\begin{bmatrix} \bm{w}_0^+(0)\\ \bm{w}_0^-(1) \end{bmatrix} = \bm{H}\bigl(\bm{w}_0^+(1),\bm{w}_0^-(0),\bm{U}(0)\bigr),
\end{align}
there exists $t 
\ensuremath{_\textnormal{max}} \in \mathbb{R}_{>0}$ such that the ODE--PDE system~\eqref{eq:ODE--PDEsystem} admits a unique \emph{generalised solution} $(\bm{X},\bm{w}) \in C^0\bigl([0,1]\times [0,t 
\ensuremath{_\textnormal{max}});\mathbb{R}^{n_{X}+8})$. Moreover, if $t 
\ensuremath{_\textnormal{max}} < \infty$, then
\begin{align}\label{eq:explosion}
 \lim_{t\uparrow t 
\ensuremath{_\textnormal{max}}}  \norm{(\bm{X}(\cdot,t), \bm{w}(\cdot,t))}_{C^0([0,1];\mathbb{R}^{n_{X}+8})} = \infty. 
\end{align}
\begin{proof}
The proof is given in Appendix~\ref{sect:App1}.
\end{proof}

\label{thm:global} 
Under the same assumptions as Theorem~\ref{thm:Local}, suppose additionally that there exist constants $L_G,M_G\in \mathbb{R}_{\geq 0}$ such that
\begin{align}\label{eq:globalEstimateG}
\norm{\bm{G}(\bm{X},\bm{w},z)}_{\ell^1(\mathbb{R}^8)} \leq M_G+L_G\norm{(\bm{X},\bm{w})}_{\ell^1(\mathbb{R}^{n_{X}+8})}, \quad (\bm{X},\bm{w},z) \in \mathbb{R}^{n_{X}+8}\times[0,1].
\end{align}
Then, the unique generalised solution extends globally in time, that is, $t 
\ensuremath{_\textnormal{max}} = \infty$ in Theorem~\ref{thm:Local}, and $(\bm{X},\bm{w})\in C^0([0,1]\times\mathbb{R}_{\geq 0};\mathbb{R}^{n_{X}+8})$. 
\begin{proof}
The proof is given in Appendix~\ref{sect:App2}.
\end{proof}

\label{lemma:friction}
Under the same assumptions as Theorem~\ref{thm:Local}, consider the ODE subsystem~\eqref{eq:ODE} with dynamics~\eqref{eq:ODEi}, and suppose that the function $g \in C^0(\mathbb{R}\times[0,1];\mathbb{R}_{\geq 0})$ reads as in Eq.~\eqref{eq:g_mu}, with $\abs{v}_\varepsilon = \sqrt{v^2 + \varepsilon}$ for $\varepsilon \in \mathbb{R}_{\geq 0}$, and the friction coefficient $\mu \in C^0(\mathbb{R}\times[0,1];[\mu 
\ensuremath{_\textnormal{min}},\infty))$ satisfying the linear growth condition
\begin{align}\label{eq:boundMu}
 \mu(v,z)\leq \mu_1(z)+\mu_2(z)\abs{v}_\varepsilon, \quad (v,z)\in\mathbb R\times[0,1].
\end{align}
Then, there exist constants $C_{f1}(\bm{X}_0(\cdot)),C_{X1}(\bm{X}_0(\cdot)),C_{f2},C_{X2} \in \mathbb{R}_{\geq 0}$ such that
\begin{subequations}
\begin{align}
\norm{f(\cdot,t)}_{C^0([0,1];\mathbb{R})} & \leq C_{f1}\bigl(\bm{X}_0(\cdot)\bigr) +C_{f2}\sup_{t^\prime \in [0,t]}\norm{v(\cdot,t)}_{C^0([0,1];\mathbb{R})},  \label{eq:boundfDOUS}\\
\norm{\bm{X}(\cdot,t)}_{C^0([0,1];\mathbb{R}^{n_{X}})} & \leq C_{X1}\bigl(\bm{X}_0(\cdot)\bigr) +C_{X2}\sup_{t^\prime \in [0,t]}\norm{v(\cdot,t)}_{C^0([0,1];\mathbb{R})}, \quad t\in [0,T],\label{eq:boundfDOUSX}
\end{align}
\end{subequations} 
for all $T \in (0, t 
\ensuremath{_\textnormal{max}})$.
In particular,
\begin{align}\label{eq:constCf2}
C_{f2} & \triangleq \sup_{z\in[0,1]} \dfrac{2\bar{k}_0(z)}{q_f(z)} \max\bigl\{\mu_2(z),1\bigr\},
\end{align}
where $\mathbb{R}_{>0} \ni q_f(z) \triangleq 2\lambda 
\ensuremath{_\textnormal{min}}(\mathbf{Q}(z))$, with $\lambda 
\ensuremath{_\textnormal{min}}(\mathbf{Q}(z))$ denoting the smallest eigenvalue of the matrix $\mathbf{Sym}_{n_X}(\mathbb{R}) \ni \mathbf{Q}(z) \succ \mathbf{0}$, with entries
\begin{subequations}
\begin{align}
Q_{0,0}(z) & \triangleq \bar{k}_0(z)+ \sum_{i=1}^{n_1}\dfrac{\bar{k}_0(z)}{\bar{c}_{i,1}(z)}+ \sum_{i=1}^{n_2}\dfrac{\bar{k}_0(z)}{\bar{c}_{i,2}(z)}, \\
Q_{0,i}(z)  = Q_{i,0}(z) & \triangleq - \sqrt{\dfrac{\bar{k}_0(z)}{\bar{c}_{i,1}(z)\tau_{i,1}(z)}}, && i \in \{1,\dots,n_1\}, \\
Q_{0,n_1+i}(z) = Q_{n_1+i,0}(z) & \triangleq \sqrt{\dfrac{\bar{k}_0(z)}{\bar{c}_{i,2}(z)\tau_{i,2}(z)}}, && i \in \{1,\dots,n_2\}, \\
Q_{i,i}(z) & \triangleq \dfrac{1}{\tau_{i,1}(z)}, && i \in \{1,\dots,n_1\}, \\
Q_{n_1+i,n_1+i}(z) & \triangleq \dfrac{1}{\tau_{i,2}(z)}, && i \in \{1,\dots,n_2\}. 
\end{align}
\end{subequations}
and all remaining off-diagonal elements equal to zero.
\begin{proof}
The proof is given in Appendix~\ref{app:proofLemmaFric}.
\end{proof}

\label{thm:Stability}
Suppose that, for $\bm{w}(\cdot,t) \in \overline{\mathcal{B}}_w$, the bounds in Eq.~\eqref{eq:boundsg_ihi} hold, and there exists a vector $\mathbb{R}^{12}\ni \bm{\eta} = [\bm{\eta}_1^{\mathrm{T}}\; \bm{\eta}_2^{\mathrm{T}}\; \bm{\eta}_3^{\mathrm{T}}\; \bm{\eta}_4^{\mathrm{T}}]^{\mathrm{T}}$, with $\mathbb{R}^3 \ni \bm{\eta}_i = [\eta_{i1}\; \eta_{i2}\; \eta_{i3}]^{\mathrm{T}}$ satisfying $\sum_{j=1}^3 \eta_{ij}^{-1} = 1$, $i \in \{1,2,3,4\}$, such that
\begin{align}\label{eq:SpectralRadius}
\rho\Bigl(\mathbf{\Theta}\bigl(\bm{\phi}_f(\overline{\bm{w}}),\bm{\eta},\overline{\bm{w}}\bigr)\Bigr) < 1,
\end{align}
 where $\rho(\mathbf{\Theta}(\bm{\phi}_f(\overline{\bm{w}}),\bm{\eta},\overline{\bm{w}}))$ denotes the spectral radius of the matrix-valued function $\mathbf{\Theta}(\cdot,\cdot,\overline{\bm{w}}) \in C^0(\mathbb{R}_{> 0}^{16};\mathbf{M}_4(\mathbb{R}_{\geq 0}))$, reading
\begin{align}\label{eq:MathTheta}
\mathbf{\Theta}(\bm{\phi}_f,\bm{\eta},\overline{\bm{w}}) \triangleq \begin{bmatrix} \theta_{11}(\bm{\eta},\overline{\bm{w}}) & \theta_{12}(\bm{\eta},\overline{\bm{w}})& \theta_{13}(\bm{\eta},\overline{\bm{w}}) & \theta_{14}(\bm{\phi}_f,\bm{\eta},\overline{\bm{w}}) \\
\theta_{21}(\bm{\eta},\overline{\bm{w}}) & \theta_{22}(\bm{\eta},\overline{\bm{w}}) & \theta_{23}(\bm{\eta},\overline{\bm{w}}) & \theta_{24}(\bm{\phi}_f,\bm{\eta},\overline{\bm{w}})\\
\theta_{31}(\bm{\eta},\overline{\bm{w}}) & \theta_{32}(\bm{\eta},\overline{\bm{w}}) & \theta_{33}(\bm{\eta},\overline{\bm{w}}) & \theta_{34}(\bm{\phi}_f,\bm{\eta},\overline{\bm{w}})\\
\theta_{41}(\bm{\eta},\overline{\bm{w}}) & \theta_{42}(\bm{\eta},\overline{\bm{w}}) & \theta_{43}(\bm{\eta},\overline{\bm{w}}) & \theta_{44}(\bm{\phi}_f,\bm{\eta},\overline{\bm{w}})\end{bmatrix},
\end{align}
with
\begin{subequations}\label{coefficientsTheta}
\begin{align}
\theta_{ij}(\bm{\eta},\overline{\bm{w}}) &\triangleq \eta_{i1}K_{i2}\psi_{ij} + \eta_{i2}K_{i3}\phi_{ij}(\overline{\bm{w}}), && i \in\{1,2,3,4\},\;j \in \{1,2,3\}, \\
\theta_{i4}(\bm{\phi}_f,\bm{\eta},\overline{\bm{w}}) & \triangleq \eta_{i1}K_{i2}\psi_{i4} + \eta_{i2}K_{i3}\phi_{i4}(\overline{\bm{w}}) +\eta_{i3}K_{i3}\phi_{if}C_{f2}C_v, && i \in \{1,2,3,4\}.
\end{align}
\end{subequations}
where the coefficients $K_{ij}\in \mathbb{R}_{>0}$, $i \in \{1,2,3,4\}$, $j \in \{1,2,3\}$ are defined as
\begin{align}\label{coeffs:K}
K_{11} & \triangleq \sup_{0\leq z^\prime \leq z \leq 1}\sqrt{1 + \alpha_1^2(z,z^\prime)} + \abs{\alpha_1(z,z^\prime)}, \quad K_{12} \triangleq \sup_{z\in[0,1]}\sqrt{1 + \alpha_1^2(z,0)} + \abs{\alpha_1(z,0)}, \nonumber \\
K_{13} & \triangleq \dfrac{1}{\lambda_1} \sup_{z \in [0,1]} \int_0^z\biggl(\sqrt{1 + \alpha_1^2(z,z^\prime)} + \abs{\alpha_1(z,z^\prime)}\biggr) \dif z^\prime, \nonumber \\
K_{21} & \triangleq \sup_{0\leq z^\prime \leq z \leq 1}\sqrt{1 + \alpha_2^2(z,z^\prime)} + \abs{\alpha_2(z,z^\prime)}, \quad K_{22} \triangleq \sup_{z\in[0,1]}\sqrt{1 + \alpha_2^2(z,0)} + \abs{\alpha_2(z,0)}, \nonumber \\
K_{23} & \triangleq \dfrac{1}{\lambda_2} \sup_{z \in [0,1]} \int_0^z\biggl(\sqrt{1 + \alpha_2^2(z,z^\prime)} + \abs{\alpha_2(z,z^\prime)}\biggr) \dif z^\prime,  \nonumber \\
K_{31} & \triangleq \sup_{0\leq z^\prime \leq z \leq 1}\sqrt{1 + \alpha_3^2(z,z^\prime)} + \abs{\alpha_3(z,z^\prime)}, \quad K_{32} \triangleq \sup_{z\in[0,1]}\sqrt{1 + \alpha_3^2(z,0)} + \abs{\alpha_3(z,0)}, \nonumber \\
K_{33} & \triangleq \dfrac{1}{\lambda_3} \sup_{z \in [0,1]} \int_0^z\biggl(\sqrt{1 + \alpha_3^2(z,z^\prime)} + \abs{\alpha_3(z,z^\prime)}\biggr) \dif z^\prime,  \nonumber \\
K_{42} & \triangleq 1,  \quad K_{41} \triangleq 1, \quad K_{43} \triangleq \dfrac{1}{\lambda_4},
\end{align}
and the functions $\alpha_i \in C^0([0,1]^2;\mathbb{R}_{\geq 0})$, $i \in \{1,2,3\}$, are given by
\begin{align}\label{eq:functionsAlpha}
\alpha_1(z,\tilde{z}) & \triangleq\dfrac{1}{2} \log\biggl( \dfrac{A 
\ensuremath{_\textnormal{p}}(z)}{A 
\ensuremath{_\textnormal{p}}(\tilde{z})}\biggr), \quad \alpha_2(z,\tilde{z}) \triangleq\dfrac{1}{2} \log\biggl( \dfrac{A 
\ensuremath{_\textnormal{a}}(z)}{A 
\ensuremath{_\textnormal{a}}(\tilde{z})}\biggr), \quad \alpha_3(z,\tilde{z}) \triangleq \dfrac{1}{2}\log\biggl( \dfrac{A 
\ensuremath{_\textnormal{b}}(z)}{A 
\ensuremath{_\textnormal{b}}(\tilde{z})}\biggr), \quad 0\leq \tilde{z}\leq z \leq 1.
\end{align}
Then, under the same assumptions as Theorem~\ref{thm:Local} and Lemma~\ref{lemma:friction}, for all inputs $\bm{U}\in C^0(\mathbb{R}_{\geq 0};\mathbb{R}^{n_U})$ and ICs $(\bm{X}_0,\bm{w}_0) \in C^0([0,1];\mathbb{R}^{n_X})\times \overline{\mathcal{B}}_w$ satisfying
\begin{align}\label{eq:condInitiDHDD}
\mathbf{A}(0)\begin{bmatrix} \norm{\bm{w}_{1,0}(\cdot)}_{C^0([0,1];\ell^2(\mathbb{R}^2))}\\ \norm{\bm{w}_{2,0}(\cdot)}_{C^0([0,1];\ell^2(\mathbb{R}^2))} \\ \norm{\bm{w}_{3,0}(\cdot)}_{C^0([0,1];\ell^2(\mathbb{R}^2))} \\ \norm{\bm{w}_{4,0}(\cdot)}_{C^0([0,1];\ell^2(\mathbb{R}^2))}\end{bmatrix}+ \mathbf{B}\bigl(\bm{\phi}_f(\overline{\bm{w}}),\bm{\eta}, \overline{\bm{w}}\bigr)\begin{bmatrix}C_{f1}\bigl(\bm{X}_0(\cdot)\bigr) \\  \norm{\bm{g}_0(\cdot)}_{C^0([0,1];\ell^2(\mathbb{R}^8))} \\ \sup_{t \in \mathbb{R}_{\geq 0}}\norm{\bm{h}_0(t)}_{\ell^2(\mathbb{R}^8)} \end{bmatrix}< \Bigl(\mathbf{I}_4-\mathbf{\Theta}\bigl(\bm{\phi}_f(\overline{\bm{w}}),\bm{\eta},\overline{\bm{w}}\bigr)\Bigr)\overline{\bm{w}},
\end{align}
with the matrices $\mathbf{A}\in C^0(\mathbb{R}_{\geq 0};\mathbf{M}_4(\mathbb{R}_{\geq 0}))$ and $\mathbf{B}(\bm{\phi}_f,\bm{\eta},\overline{\bm{w}}) \in \mathbf{M}_{4\times3}(\mathbb{R}_{\geq 0})$ reading
\begin{subequations}\label{eq:matricesAB}
\begin{align}
\mathbf{A}(\varrho) & \triangleq \begin{bmatrix} K_{11}\ensuremath{\mathrm{e}}^{\varrho \lambda_1^{-1}} & 0 & 0 & 0 \\
0 & K_{21}\ensuremath{\mathrm{e}}^{\varrho \lambda_2^{-1}} & 0 & 0 \\
0 & 0 & K_{31}\ensuremath{\mathrm{e}}^{\varrho \lambda_3^{-1}} & 0 \\
0 & 0 & 0 & K_{41}\ensuremath{\mathrm{e}}^{\varrho \lambda_4^{-1}} \end{bmatrix}, \\
\mathbf{B}(\bm{\phi}_f,\bm{\eta}, \overline{\bm{w}}) & \triangleq \begin{bmatrix} 
b_{11}(\bm{\phi}_f,\bm{\eta}) & b_{12}(\bm{\eta},\overline{\bm{w}}) & b_{13}(\bm{\eta}) \\
b_{21}(\bm{\phi}_f,\bm{\eta}) & b_{22}(\bm{\eta},\overline{\bm{w}}) & b_{23}(\bm{\eta}) \\
b_{31}(\bm{\phi}_f,\bm{\eta})  & b_{32}(\bm{\eta},\overline{\bm{w}}) & b_{33}(\bm{\eta}) \\
b_{41} (\bm{\phi}_f,\bm{\eta})& b_{42}(\bm{\eta},\overline{\bm{w}}) & b_{43}(\bm{\eta}) \\ \end{bmatrix},
\end{align}
\end{subequations}
where
\begin{subequations}
\begin{align}
b_{i1}(\bm{\phi}_f,\bm{\eta}) & \triangleq \eta_{i3}K_{i3}\phi_{if}, \\
b_{i2}(\bm{\eta},\overline{\bm{w}}) & \triangleq (1+\eta_i^{-1})K_{i3}\phi_{i0}(\overline{\bm{w}}),  \\
b_{i3}(\bm{\eta}) & \triangleq (1+\eta_i)K_{i2}\psi_{i0}, && i \in\{1,2,3,4\},
\end{align}
\end{subequations}
the ODE--PDE system~\eqref{eq:ODE--PDEsystem} admits a unique bounded, global generalised solution $(\bm{X},\bm{w})\in C^0([0,1]\times\mathbb{R}_{\geq 0};\mathbb{R}^{n_{X}+8})$ which is \emph{input-to-state-stable} in the PDE variables.
More precisely, $\bm{w}(\cdot,t) \in \overline{\mathcal{B}}_w$ for all $t \in \mathbb{R}_{\geq 0}$, and there exist $\Theta_X,\Theta_w,\gamma,\delta \in \mathbb{R}_{>0}$ such that 
\begin{subequations}\label{eq:BoundedandISSEst}
\begin{align}
\begin{split}
& \norm{\bm{w}(\cdot,t)}_{C^0([0,1];\mathbb{R}^{8})} \leq \Theta_w\norm{\bm{w}_0(\cdot)}_{C^0([0,1];\mathbb{R}^8)}\ensuremath{\mathrm{e}}^{-\delta t} \\
& \qquad + \gamma\Biggl(C_{f1}\bigl(\bm{X}_0(\cdot)\bigr) + \norm{\bm{g}_0(\cdot)}_{C^0([0,1];\mathbb{R}^8)} + \sup_{t^\prime\in[0,t]}\norm{\bm{h}_0(t^\prime)}_{\mathbb{R}^8} \Biggr), 
\end{split}\label{eq:BoundedandISSEst1} \\
\begin{split}
& \norm{(\bm{X}(\cdot,t),\bm{w}(\cdot,t))}_{C^0([0,1];\mathbb{R}^{n_{X}+8})} \leq \Theta_X\norm{\bm{w}_0(\cdot)}_{C^0([0,1];\mathbb{R}^8)} \\
& \qquad + \gamma\Biggl(C_{X1}\bigl(\bm{X}_0(\cdot)\bigr) + C_{f1}\bigl(\bm{X}_0(\cdot)\bigr) + \norm{\bm{g}_0(\cdot)}_{C^0([0,1];\mathbb{R}^8)} + \sup_{t^\prime\in[0,t]}\norm{\bm{h}_0(t^\prime)}_{\mathbb{R}^8} \Biggr), \quad t\in \mathbb{R}_{\geq 0}. \label{eq:BoundedandISSEst2}
\end{split}
\end{align}
\end{subequations}
\begin{proof}
The proof is given in Appendix~\ref{app:finalProod}.
\end{proof}

First, it should be remarked that, under the same assumptions as Theorem~\ref{thm:Local}, the ODE--PDE system~\eqref{eq:ODE--PDEsystem} admits a unique generalised solution $(\bm{X},\bm{w})\in C^0([0,1]\times [0,T];\mathbb{R}^{n_{X}+8})$ on every finite interval $[0,T]$ with $T \in (0,t 
\ensuremath{_\textnormal{max}})$. In particular, combined with Eq.~\eqref{eq:ODE}, this type of regularity also ensures $\bm{X}(\cdot,z) \in C^1([0,T];\mathbb{R}^{n_{X}})$.
Accordingly, the following Lyapunov function is considered:
\begin{align}\label{eq:Lyapunov}
\begin{split}
V\bigl(\bm{X}(z,t)\bigr) \triangleq & \dfrac{1}{2}\bigggl( \dfrac{f^2(z,t)}{\bar{k}_0(z,t)} + \sum_{i=1}^{n_1}\dfrac{\bar{c}_{i,1}(z,t)}{\tau_{i,1}(z)}x_{i,1}^2(z,t) + \sum_{i=1}^{n_2}\dfrac{\bar{c}_{i,2}(z,t)}{\tau_{i,2}(z)}x_{i,2}^2(z,t)\bigggr),
\end{split}
\end{align}
which is differentiable with respect to time in the classical sense.
In fact, taking the time derivative of Eq.~\eqref{eq:Lyapunov} along the dynamics~\eqref{eq:ODEi} yields
\begin{align}
\begin{split}
\dpd{V(z,t)}{t} & \leq \abs{v(z,t)}_\varepsilon\abs{f(z,t)} - \dfrac{\abs{v(z,t)}_\varepsilon}{\mu\bigl(v(z,t),z\bigr)}f^2(z,t) \\
& \quad - \sum_{i=1}^{n_1}\bar{c}_{i,1}(z)\biggl(\dpd{x_{i,1}(z,t)}{t}\biggr)^2 - \sum_{i=1}^{n_2}\bar{c}_{i,2}(z)\biggl(\dpd{x_{i,2}(z,t)}{t}\biggr)^2,  \\
& \leq \abs{v(z,t)}_\varepsilon\abs{f(z,t)} - \abs{v(z,t)}_\varepsilon \min\Biggl\{\dfrac{1}{\mu\bigl(v(z,t),z\bigr)},\dfrac{1}{\abs{v(z,t)}_\varepsilon}\Biggr\}\\
& \quad  \times \bigggl[ f^2(z,t) + \sum_{i=1}^{n_1}\bar{c}_{i,1}(z)\biggl(\dpd{x_{i,1}(z,t)}{t}\biggr)^2 + \sum_{i=1}^{n_2}\bar{c}_{i,2}(z)\biggl(\dpd{x_{i,2}(z,t)}{t}\biggr)^2 \bigggr], \quad (z,t) \in [0,1]\times [0,T]. 
\end{split}
\end{align}
Recalling Eq.~\eqref{eq:Lyapunov}, lengthy but straightforward manipulations lead in turn to
\begin{align}
\begin{split}
\dpd{V(z,t)}{t} & \leq \abs{v(z,t)}_\varepsilon\sqrt{2\bar{k}_0(z)} \sqrt{V(z,t)} \\
& \quad - \abs{v(z,t)}_\varepsilon q_f(z)\min\Biggl\{\dfrac{1}{\mu\bigl(v(z,t),z\bigr)},\dfrac{1}{\abs{v(z,t)}_\varepsilon}\Biggr\}V(z,t), \quad (z,t) \in [0,1]\times[0,T],
\end{split}
\end{align}
where $\mathbb{R}_{>0} \ni q_f(z) \triangleq 2\lambda 
\ensuremath{_\textnormal{min}}(\mathbf{Q}(z))$.
Furthermore, defining $W(\bm{X}(z,t)) \triangleq \sqrt{V(\bm{X}(z,t))}$ with some abuse of notation yields, for $W(z,t) > 0$,
\begin{align}
\begin{split}
\dpd{W(z,t)}{t} &\leq -\dfrac{q_f(z)}{2} \min\Biggl\{\dfrac{\abs{v(z,t)}_\varepsilon}{\mu\bigl(v(z,t),z\bigr)},1\Biggr\} \\
& \quad \times \biggl[ W(z,t) - \dfrac{\sqrt{2\bar{k}_0(z)}}{q_f(z)} \max\Bigl\{\mu\bigl(v(z,t),z\bigr),\abs{v(z,t)}_\varepsilon\Bigr\} \biggr], \quad (z,t) \in [0,1]\times [0,T].
\end{split}
\end{align}
Thus, by comparison
\begin{align}\label{eq:Wcomp}
W(z,t) \leq \max\Biggl\{ W(z,0), \dfrac{\sqrt{2\bar{k}_0(z)}}{q_f(z)} \sup_{t^\prime\in[0,t]} \max\Bigl\{\mu\bigl(v(z,t^\prime),z\bigr),\abs{v(z,t^\prime)}_\varepsilon\Bigr\} \Biggr\}, \quad (z,t) \in [0,1]\times[0,T].
\end{align} 
Multiplying Eq.~\eqref{eq:Wcomp} by $\sqrt{2\bar{k}_0(z)}$, and using $\abs{f(z,t)}\leq \sqrt{2\bar{k}_0(z)}W(z,t)$ also gives
\begin{align}\label{eq:fcomp}
\abs{f(z,t)} \leq \max\Biggl\{ \sqrt{2\bar{k}_0(z)V(z,0)}, \frac{2\bar{k}_0(z)}{q_f(z)} \sup_{t^\prime\in[0,t]} \max\Bigl\{\mu\bigl(v(z,t^\prime),z\bigr),\abs{v(z,t^\prime)}_\varepsilon\Bigr\} \Biggr\}, \quad (z,t) \in [0,1]\times[0,T].
\end{align} 
Moreover, utilising the bound in Eq.~\eqref{eq:boundMu} and observing that $\abs{v}_\varepsilon=\sqrt{v^2+\varepsilon} \leq \abs{v}+\sqrt{\varepsilon}$ for all $\varepsilon \in \mathbb{R}_{\geq 0}$, the following inequality is deduced:
\begin{align}
\max\bigl\{\mu(v,z),\abs{v}_\varepsilon\bigr\} \leq \mu_1(z) + \max\bigl\{\mu_2(z),1\bigr\}\sqrt{\varepsilon} + \max\bigl\{\mu_2(z),1\bigr\}\abs{v}, \quad (v,z) \in \mathbb{R}\times[0,1],
\end{align}
which implies
\begin{align}\label{eq:boundsupMu}
\sup_{t^\prime\in[0,t]} \max\Bigl\{\mu\bigl(v(z,t^\prime\bigr),z),\abs{v}_\varepsilon\Bigr\} \leq \mu_1(z) + \max\bigl\{\mu_2(z),1\bigr\}\sqrt{\varepsilon} & + \max\bigl\{\mu_2(z),1\bigr\}\sup_{t^\prime\in[0,t]} \abs{v(z,t^\prime)}, \\
& \quad (v,z) \in C^0([0,1]\times[0,T];\mathbb{R})\times[0,1].
\end{align}
From Eqs.~\eqref{eq:Wcomp},~\eqref{eq:fcomp},~\eqref{eq:boundsupMu}, it follows that
\begin{subequations}
\begin{align}
W(z,t) & \leq \max\Biggl\{ W(z,0), \frac{\sqrt{2\bar{k}_0(z)}}{q_f(z)} \bigl[ \mu_1(z) + \max\{\mu_2(z),1\}\sqrt{\varepsilon} \bigr] + \frac{\sqrt{2k_0(z)}}{q_f(z)} \max\{\mu_2(z),1\} \sup_{t^\prime\in[0,t]}\abs{v(z,t^\prime)} \Biggr\}, \\
\abs{f(z,t)} & \leq \max\Biggl\{ \sqrt{2\bar{k}_0(z)V(z,0)}, \dfrac{2\bar{k}_0(z)}{q_f(z)} \bigl[ \mu_1(z) + \max\{\mu_2(z),1\}\sqrt{\varepsilon} \bigr] + \dfrac{2\bar{k}_0(z)}{q_f(z)} \max\{\mu_2(z),1\} \sup_{t^\prime\in[0,t]}\abs{v(z,t^\prime)} \Biggr\}.
\end{align}
\end{subequations}
Using the elementary inequality $\max\{a,c+dM\}\leq\max\{a,c\}+dM$ that holds for all $a,c,d,M \in \mathbb{R}_{\geq 0}$, it may be concluded that
\begin{subequations}
\begin{align}
\norm{W(\cdot,z)}_{C^0([0,1];\mathbb{R})}& \leq C_{W1} + C_{W2}\sup_{t^\prime\in[0,t]}\norm{v(\cdot,t^\prime)}_{C^0([0,1];\mathbb{R})}, \label{eq:finalBoundsfWW}\\
\norm{f(\cdot,z)}_{C^0([0,1];\mathbb{R})} & \leq C_{f1}\bigl(\bm{X}_0(\cdot)\bigr) + C_{f2}\sup_{t^\prime\in[0,t]}\norm{v(\cdot,t^\prime)}_{C^0([0,1];\mathbb{R})}, && t \in [0,T],\label{eq:finalBoundsfWf}
\end{align}
\end{subequations} 
with $C_{W1}(\bm{X}_0(\cdot)), C_{f1}(\bm{X}_0(\cdot)), C_{W2}, C_{f2} \in \mathbb{R}_{\geq 0}$ given by
\begin{subequations}
\begin{align}
C_{W1}\bigl(\bm{X}_0(\cdot)\bigr) & \triangleq \sup_{z\in[0,1]} \max\Biggl\{ W\bigl(\bm{X}_0(z)\bigr), \dfrac{\sqrt{2\bar{k}_0(z)}}{q_f(z)} \bigl[ \mu_1(z) + \max\{\mu_2(z),1\}\sqrt{\varepsilon} \bigr] \Biggr\},\label{eq:constCW1fb} \\
C_{W2} & \triangleq \sup_{z\in[0,1]} \dfrac{\sqrt{2\bar{k}_0(z)}}{q_f(z)} \max\bigl\{\mu_2(z),1\bigr\}, \label{eq:constC21fb}\\
C_{f1}\bigl(\bm{X}_0(\cdot)\bigr)  & \triangleq \sup_{z\in[0,1]} \max\Biggl\{ \sqrt{2\bar{k}_0(z)V\bigl(\bm{X}_0(z)\bigr)}, \dfrac{2\bar{k}_0(z)}{q_f(z)} \bigl[ \mu_1(z) + \max\{\mu_2(z),1\}\sqrt{\varepsilon} \bigr] \Biggr\}, \label{eq:constCf1fb}\\
C_{f2} & \triangleq \sup_{z\in[0,1]} \dfrac{2\bar{k}_0(z)}{q_f(z)} \max\bigl\{\mu_2(z),1\bigr\}. \label{eq:constCf2fb}
\end{align}
\end{subequations}
Equations~\eqref{eq:finalBoundsfWf},~\eqref{eq:constCf1fb}, and~\eqref{eq:constCf2fb} prove~\eqref{eq:boundfDOUS} and~\eqref{eq:constCf2}. The estimate~\eqref{eq:boundfDOUSX} is instead a consequence of Eqs.~\eqref{eq:finalBoundsfWW},~\eqref{eq:constCW1fb}, and~\eqref{eq:constCW1fb} by noting that $W(\bm{X}(z,t))$ is equivalent to a norm on $\mathbb{R}^{n_{X}}$.

The proof starts by noting that, under the stated assumptions, Theorem~\ref{thm:Local} ensures the existence of a unique, maximal generalised solution $(\bm{X},\bm{w}) \in C^0([0,t 
\ensuremath{_\textnormal{max}});C^0([0,1];\mathbb{R}^{n_X+8}))$ for some $t 
\ensuremath{_\textnormal{max}} \in \mathbb{R}_{>0}$.
To prove that the solution is global and bounded, the variables $\mathbb{R}^2 \ni \bm{\xi}_i(z,t) = [\xi_i^+(z,t)\; \xi_i^-(z,t)]^{\mathrm{T}}$, $i \in \{1,2,3,4\}$, are first introduced, with
\begin{align}\label{eq:xiRdos}
\xi_i^{+}(z,t) \triangleq w_i^{+}(z,t), && \xi_i^{-}(z,t) \triangleq w_i^{-}(1-z,t). 
\end{align}
The above transformation is an isomorphism of $C^0([0,1];\mathbb{R}^2)$. Indeed,
\begin{align}
 \norm{\bm{\xi}_i(\cdot)}_{C^0([0,1];\mathbb{R}^2)} = \norm{\bm{w}_i(\cdot)}_{C^0([0,1];\mathbb{R}^2)}, \quad i \in \{1,2,3,4\}.
\end{align}
Moreover, inserting~\eqref{eq:xiRdos} into the PDE dynamics~\eqref{eq:PDEsubst} and BC~\eqref{eq:BCs} provides
\begin{subequations}\label{eq:ODE--PDEsystemphi}
\begin{align}
\dpd{\bm{\xi}_i(z,t)}{t} + \lambda_i\dpd{\bm{\xi}_i(z,t)}{z} & = \mathbf{A}_i(z)\bm{\xi}_i(z,t) + \bm{g}_i\bigl(\bm{X}(z,t),\bm{\xi}(z,t),z\bigr), && (z,t) \in (0,1)\times(0,t 
\ensuremath{_\textnormal{max}}), \; i \in \{1,2,3,4\},\label{eq:PDEsubstphi}\\
\bm{\xi}(0,t)  & = \bm{H}\bigl(\bm{\xi}(0,t), \bm{U}(t)\bigr), && t \in (0,t 
\ensuremath{_\textnormal{max}}), \label{eq:BCxi}
\end{align}
\end{subequations}
where the matrix-valued functions $\mathbf{A}_i \in C^0([0,1];\mathbf{M}_2(\mathbb{R}))$, $i \in \{1,2,3,4\}$, read
\begin{align}
\mathbf{A}_1(z) & \triangleq \dfrac{1}{2A 
\ensuremath{_\textnormal{p}}(z)L 
\ensuremath{_\textnormal{s}}}\sqrt{\dfrac{\beta}{\rho}}\dod{A 
\ensuremath{_\textnormal{p}}(z)}{z}\begin{bmatrix} 1& -1 \\ 1 & -1\end{bmatrix},  && \mathbf{A}_2(z)  \triangleq \dfrac{1}{2A 
\ensuremath{_\textnormal{a}}(z)L 
\ensuremath{_\textnormal{s}}}\sqrt{\dfrac{\beta}{\rho}}\dod{A 
\ensuremath{_\textnormal{a}}(z)}{z}\begin{bmatrix} 1& -1 \\ 1 & -1\end{bmatrix}, \nonumber \\
\mathbf{A}_3(z) & \triangleq \dfrac{1}{2A 
\ensuremath{_\textnormal{b}}(z)L 
\ensuremath{_\textnormal{b}}}\sqrt{\dfrac{\beta}{\rho}}\dod{A 
\ensuremath{_\textnormal{b}}(z)}{z}\begin{bmatrix} 1& -1 \\ 1 & -1\end{bmatrix}, && \mathbf{A}_4(z) \triangleq \mathbf{0}.
\end{align}
Accordingly, defining $z_i(z,t,\tilde{t}) \triangleq z_i^+(z,t,\tilde{t})$ and $\tau_i(z,t) \triangleq \tau_i^+(z,t)$, $i \in \{1,2,3,4\}$, as in~\eqref{eq:tauZ+}, integrating Eq.~\eqref{eq:PDEsubstphi} along the characteristic lines and imposing the BC~\eqref{eq:BCxi} yields
\begin{subequations}\label{eq:solutionZI}
\begin{align}
\begin{split}
\bm{\xi}_i(z,t) & = \mathbf{\Phi}_i\bigl(z,z_i(z,t,0)\bigr)\bm{\xi}_{i,0}\bigl(z_i(z,t,0)\bigr)  \\
& \quad + \int_0^t \mathbf{\Phi}_i\bigl(z,z_i(z,t,t^\prime)\bigr) \widetilde{\bm{g}}_i\bigl(z_i(z,t,t^\prime),t^\prime\bigr) \dif t^\prime, \quad \tau_i(z,t) \leq 0, 
\end{split} \\
\begin{split}
\bm{\xi}_i(z,t) & =\mathbf{\Phi}_i(z,0) \widetilde{\bm{h}}_i\bigl(\tau_i(z,t)\bigr) \\
& \quad + \int_{\tau_i(z,t)}^t \mathbf{\Phi}_i\bigl(z,z_i(z,t,t^\prime)\bigr) \widetilde{\bm{g}}_i\bigl(z_i(z,t,t^\prime),t^\prime\bigr) \dif t^\prime, \quad \tau_i(z,t) > 0, \; i \in \{1,2,3,4\},
\end{split}
\end{align}
\end{subequations}
where the spatial state-transition matrices $\mathbf{\Phi}_i(z,\tilde{z}) \in \mathbf{M}_2(\mathbb{R})$ generated by $\mathbf{A}_i(z)$, $i \in \{1,2,3,4\}$, write
\begin{align}
\mathbf{\Phi}_1(z,\tilde{z}) & \triangleq \mathbf{I}_2 + \dfrac{1}{2}\log\biggl( \dfrac{A 
\ensuremath{_\textnormal{p}}(z)}{A 
\ensuremath{_\textnormal{p}}(\tilde{z})}\biggr) \begin{bmatrix}1 & -1\\ 1 & -1\end{bmatrix}, 
&& \mathbf{\Phi}_2(z,\tilde{z}) \triangleq \mathbf{I}_2 + \dfrac{1}{2}\log\biggl( \dfrac{A 
\ensuremath{_\textnormal{a}}(z)}{A 
\ensuremath{_\textnormal{a}}(\tilde{z})}\biggr) \begin{bmatrix}1 & -1\\ 1 & -1\end{bmatrix}, \nonumber \\
\mathbf{\Phi}_3(z,\tilde{z}) & \triangleq \mathbf{I}_2 + \dfrac{1}{2}\log\biggl( \dfrac{A 
\ensuremath{_\textnormal{b}}(z)}{A 
\ensuremath{_\textnormal{b}}(\tilde{z})}\biggr) \begin{bmatrix}1 & -1\\ 1 & -1\end{bmatrix}, &&
\mathbf{\Phi}_4(z,\tilde{z}) \triangleq \mathbf{I}_2.
\end{align}
The next step consists of estimating upper bounds for the different components of the solution~\eqref{eq:solutionZI}. To this end, the vectors $\mathbb{R}_{\geq 0}^4 \ni \bm{W}(t) \triangleq [W_{1}\; W_{2}\; W_{3}\; W_{4}]^{\mathrm{T}}$, $\mathbb{R}_{\geq 0}^4 \ni \bm{W}_0(t) =  [W_{0,1}\; W_{0,2}\; W_{0,3}\; W_{0,4}]^{\mathrm{T}} \triangleq \bm{W}(0)$, and $\bm{\beta}\in \mathbb{R}_{\geq 0}^3$ are first defined as
\begin{subequations}\label{eq:W0Betas}
\begin{align}
W_{i}(t) & \triangleq  \norm{\bm{w}_{i}(\cdot, t)}_{C^0([0,1];\ell^2(\mathbb{R}^2))}, \\
W_{0,i} & \triangleq  \norm{\bm{w}_{i,0}(\cdot)}_{C^0([0,1];\ell^2(\mathbb{R}^2))}, && i \in \{1,2,3,4\}, \\
\bm{\beta}(t) & \triangleq \begin{bmatrix} C_{f1}\bigl(\bm{X}_0(\cdot)\bigr)\\ \norm{\bm{g}_0(\cdot)}_{C^0([0,1];\ell^2(\mathbb{R}^8))}, \\ \sup_{t \in \mathbb{R}_{\geq 0}} \norm{\bm{h}_0(t)}_{\ell^2(\mathbb{R}^8)} \end{bmatrix}.
\end{align}
\end{subequations}
Utilising Eq.~\eqref{eq:W0Betas}, it may be observed that the condition~\eqref{eq:condInitiDHDD} implies that 
\begin{align}\label{eq:condInitiDHDD2}
\mathbf{A}(0)\bm{W}_0+ \mathbf{B}\bigl(\bm{\phi}_f(\overline{\bm{w}}),\bm{\eta}, \overline{\bm{w}}\bigr)\bm{\beta}(t)< \Bigl(\mathbf{I}_4-\mathbf{\Theta}\bigl(\bm{\phi}_f(\overline{\bm{w}}),\bm{\eta},\overline{\bm{w}}\bigr)\Bigr)\overline{\bm{w}},
\end{align}
and, since $\mathbf{B}(\bm{\phi}_f(\overline{\bm{w}}),\bm{\eta},\overline{\bm{w}}) \in \mathbf{M}_{4\times 3}(\mathbb{R}_{\geq 0})$, also
\begin{align} 
\mathbf{A}(0)\bm{W}_0 < \Bigl( \mathbf{I}_4- \mathbf{\Theta} \bigl( \bm{\phi}_f(\overline{\bm{w}}), \bm{\eta}, \overline{\bm{w}} \bigr) \Bigr) \overline{\bm{w}} \leq \overline{\bm{w}}. 
\end{align} 
Moreover, by Eq.~\eqref{coeffs:K}, $\mathbf{A}(0)\succeq \mathbf{I}_4$, yielding $\bm{W}_0<\overline{\bm{w}}$ and thus $\bm{w}_0 \in \operatorname{int}\overline{\mathcal{B}}_w$. Consequently, by continuity of $t\mapsto\bm{w}(\cdot,t)$ in $C^0([0,1];\mathbb{R}^8)$, the first-exit time 
\begin{align}\label{eq:firstExitTime} 
t_{w} \triangleq \inf\Bigl\{ t\in[0,t_{\max}) \mathrel{\Big|} \bm{w}(\cdot,t) \notin \operatorname{int}\overline{\mathcal{B}}_w \Bigr\}, 
\end{align} 
with the convention $\inf\varnothing=t_{\max}$, is strictly positive, i.e., $t_w \in \mathbb{R}_{>0}$. By the definition of $t_w$, $\bm{w}(\cdot,t) \in \operatorname{int}\overline{\mathcal{B}}_w$ on every interval $t\in[0,T]$ with $T \in (0,t_w)$; therefore, all the bounds in Eq.~\eqref{eq:boundsg_i}, and in particular the coefficients $\phi_{i0}(\overline{\bm{w}})$, $\phi_{ij}(\overline{\bm{w}})$, and $\phi_{if}(\overline{\bm{w}})$, are valid throughout $[0,T]$.

Then, defining the functions $\widetilde{\bm{g}}_i, \widetilde{\bm{h}}_i \in C^0([0,1]\times[0,T];\mathbb{R}^2) $ as $\widetilde{\bm{g}}_i(z,t) \triangleq \bm{g}_i(\bm{X}(z,t),\bm{\xi}(z,t),z)$ and $\widetilde{\bm{h}}_i(z,t) \triangleq \bm{H}_i(\bm{\xi}^-(0,t),\bm{U}(t))$, $i \in \{1,2,3,4\}$, and introducing
\begin{align}
\bar{g}_i(t) & \triangleq \phi_{i0}(\overline{\bm{w}}) \norm{\bm{g}_0(\cdot)}_{C^0([0,1];\ell^2(\mathbb{R}^8))} +\sum_{j=1}^4 \phi_{ij}(\overline{\bm{w}})\norm{\bm{w}_j(\cdot,t)}_{C^0([0,1];\ell^2(\mathbb{R}^2))}, \quad i \in \{1,2,3,4\},
\end{align}
provides, in conjunction with Eq.~\eqref{eq:boundsg_i},
\begin{align}\label{eq:gbarBound}
\norm{\widetilde{\bm{g}}(\cdot,t)}_{C^0([0,1];\ell^2(\mathbb{R}^2))} \leq \bar{g}_i(t) +\phi_{if}(\overline{\bm{w}})\norm{f(\cdot,t)}_{C^0([0,1];\mathbb{R})}, \quad i \in \{1,2,3,4\}.
\end{align}
Moreover,
\begin{subequations}
\begin{align}
\norm{\mathbf{\Phi}_1(z,\tilde{z})} & = \sqrt{1 + \dfrac{1}{4}\log^2\biggl( \dfrac{A 
\ensuremath{_\textnormal{p}}(z)}{A 
\ensuremath{_\textnormal{p}}(\tilde{z})}\biggr)} +\dfrac{1}{2} \abs{\log\biggl( \dfrac{A 
\ensuremath{_\textnormal{p}}(z)}{A 
\ensuremath{_\textnormal{p}}(\tilde{z})}\biggr)} = \sqrt{1+\alpha_1^2(z,\tilde{z})} + \abs{\alpha_1(z,\tilde{z})},\\
 \norm{\mathbf{\Phi}_2(z,\tilde{z})} & = \sqrt{1 + \dfrac{1}{4}\log^2\biggl( \dfrac{A 
\ensuremath{_\textnormal{a}}(z)}{A 
\ensuremath{_\textnormal{a}}(\tilde{z})}\biggr)} +\dfrac{1}{2} \abs{\log\biggl( \dfrac{A 
\ensuremath{_\textnormal{a}}(z)}{A 
\ensuremath{_\textnormal{a}}(\tilde{z})}\biggr)}= \sqrt{1+\alpha_2^2(z,\tilde{z})} + \abs{\alpha_2(z,\tilde{z})}, \\
\norm{\mathbf{\Phi}_3(z,\tilde{z})} & = \sqrt{1 +\dfrac{1}{4} \log^2\biggl( \dfrac{A 
\ensuremath{_\textnormal{b}}(z)}{A 
\ensuremath{_\textnormal{b}}(\tilde{z})}\biggr)} + \dfrac{1}{2}\abs{\log\biggl( \dfrac{A 
\ensuremath{_\textnormal{b}}(z)}{A 
\ensuremath{_\textnormal{b}}(\tilde{z})}\biggr)}= \sqrt{1+\alpha_3^2(z,\tilde{z})} + \abs{\alpha_3(z,\tilde{z})}, \\
\norm{\mathbf{\Phi}_4(z,\tilde{z})} & = 1,
\end{align}
\end{subequations}
with $\alpha_i(z,\tilde{z})$, $i \in \{1,2,3\}$ as in Eq.~\eqref{eq:functionsAlpha}.

Hence, combining Eq.~\eqref{eq:solutionZI} with~\eqref{eq:boundfFric},~\eqref{coeffs:K}, and~\eqref{eq:gbarBound}, and exploiting the fact that the ICs vanish for $t\geq \lambda_i^{-1}$, it is possible to infer the existence of an arbitraty constant $\varrho \in \mathbb{R}_{>0}$ verifying
\begin{align}\label{eq:bound1Xi}
\begin{split}
\norm{\bm{\xi}_i(z,t)}_{\ell^2(\mathbb{R}^2)} & \leq K_{i1}\ensuremath{\mathrm{e}}^{-\varrho(t-\lambda_i^{-1})}\norm{\bm{\xi}_{i,0}(\cdot)}_{C^0([0,1];\ell^2(\mathbb{R}^2))} + K_{i2} \sup_{t^\prime\in[0,t]}\norm{\bm{\widetilde{h}}_i(t^\prime)}_{\ell^2(\mathbb{R}^2)} +K_{i3}\sup_{t^\prime\in[0,t]}\bar{g}_i(t^\prime) \\
& \quad + K_{if}(\overline{\bm{w}})\sup_{t^\prime\in[0,t]}\Bigl(C_{f1}\bigl(\bm{X}_0(\cdot)\bigr)+ C_{f2}C_v\norm{\bm{w}_4(\cdot,t^\prime)}_{C^0([0,1];\ell^2(\mathbb{R}^2))}\Bigr), \\
& \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad t \in [0,T],\; i\in \{1,2,3,4\},
\end{split}
\end{align}
with $\mathbb{R}_{\geq 0} \ni K_{if} (\overline{\bm{w}})\triangleq K_{i3}\phi_{if}(\overline{\bm{w}})$, $i \in \{1,2,3,4\}$.
Furthermore, using the fact that the inequality
\begin{align}
\begin{split}
& K_{i2} \sup_{t^\prime\in[0,t]}\norm{\bm{\widetilde{h}}_i(t^\prime)}_{\ell^2(\mathbb{R}^2)} + \quad K_{i3}\sup_{t^\prime\in[0,t]}\bar{g}_i(t^\prime) \\
& \quad + K_{if}(\overline{\bm{w}})\sup_{t^\prime\in[0,t]}\Bigl(C_{f1}\bigl(\bm{X}_0(\cdot)\bigr)+ C_{f2}C_v\norm{\bm{w}_4(\cdot,t^\prime)}_{C^0([0,1];\ell^2(\mathbb{R}^2))}\Bigr)\\
& \quad \leq \sup_{t^\prime \in [0,t]}\Biggl[ \eta_{i1}K_{i2}\norm{\bm{\widetilde{h}}_i(t^\prime)}_{\ell^2(\mathbb{R}^2)} +\eta_{i2} K_{i3}\bar{g}(t^\prime) + \eta_{i3}K_{if}(\overline{\bm{w}})\sup_{t^\prime\in[0,t]}\Bigl(C_{f1} + C_{f2}C_v\norm{\bm{w}_4(\cdot,t^\prime)}_{C^0([0,1];\ell^2(\mathbb{R}^2))}\Bigr) \Biggr]
\end{split}
\end{align}
holds for every $\eta_{i1},\eta_{i2},\eta_{i3} \in \mathbb{R}_{>0}$ satisfying $\sum_{j=1}^3 \eta_{ij}^{-1}=1$, $i \in \{1,2,3,4\}$, the following ISS estimate is obtained from Eq.~\eqref{eq:bound1Xi}:
\begin{align}
\begin{split}
&  \norm{\bm{w}_i(z,t)}_{\ell^2(\mathbb{R}^2)} \leq \sup_{t^\prime \in [0,t]}\Biggl[ \eta_{i1}K_{i2}\norm{\bm{\widetilde{h}}_i(t^\prime)}_{\ell^2(\mathbb{R}^2)} +\eta_{i2} K_{i3}\bar{g}(t^\prime) \\
& \quad + \eta_{i3}K_{if}(\overline{\bm{w}})\sup_{t^\prime\in[0,t]}\Bigl(C_{f1}\bigl(\bm{X}_0(\cdot)\bigr) + C_{f2}C_v\norm{\bm{w}_4(\cdot,t^\prime)}_{C^0([0,1];\ell^2(\mathbb{R}^2))}\Bigr) \Biggr]\\
& \qquad+  K_{i1}\ensuremath{\mathrm{e}}^{-\varrho(t-\lambda_i^{-1})}\norm{\bm{w}_{i,0}(\cdot)}_{C^0([0,1];\ell^2(\mathbb{R}^2))}, \quad t \in [0,T],\; i\in \{1,2,3,4\}.
\end{split}
\end{align}
Since the semigroup property holds for the solution~\eqref{eq:solutionZI}, $i \in\{1,2,3,4\}$, it is possible to invoke the fading memory inequality \cite[Lemma~7.1]{Krstic2} to conclude the existence of an arbitrary small constant $\epsilon \in \mathbb{R}_{>0}$ such that
\begin{align}\label{eq:fadingEstimate}
\begin{split}
&  \norm{\bm{w}_i(z,t)}_{\ell^2(\mathbb{R}^2)}\ensuremath{\mathrm{e}}^{\delta t} \\
& \quad \leq (1+\epsilon)\sup_{t^\prime \in [0,t]}\ensuremath{\mathrm{e}}^{\delta t^\prime}\biggl( \eta_{i1}K_{i2}\norm{\bm{\widetilde{h}}_i(t^\prime)}_{\ell^2(\mathbb{R}^2)} +\eta_{i2} K_{i3}\bar{g}(t^\prime) + \eta_{i3}K_{if}(\overline{\bm{w}}) C_{f2}C_v\norm{\bm{w}_4(\cdot,t^\prime)}_{C^0([0,1];\ell^2(\mathbb{R}^2))} \biggr)\\
& \qquad+  K_{i1}\ensuremath{\mathrm{e}}^{\varrho\lambda_i^{-1}}\norm{\bm{w}_{i,0}(\cdot)}_{C^0([0,1];\ell^2(\mathbb{R}^2))} +(1+\epsilon)\eta_{i3}K_{if}(\overline{\bm{w}})C_{f1}\bigl(\bm{X}_0(\cdot)\bigr)\ensuremath{\mathrm{e}}^{\delta t}, \quad t \in [0,T],\; i\in \{1,2,3,4\},
\end{split}
\end{align}
where $\delta \in (0,\varrho)$ depends only on $\varrho$ and $\lambda_i,K_{i1}$, $i \in \{1,2,3,4\}$. Consequently, recalling the bounds~\eqref{eq:boundsg_ihi} and defining the vectors $\mathbb{R}_{\geq 0}^4 \ni \bm{W}^\delta(t) \triangleq [W_1^\delta(t)\; W_2^\delta(t)\; W_3^\delta(t)\; W_4^\delta(t)]^{\mathrm{T}}$ and $\bm{\beta}^\delta (t) \in \mathbb{R}_{\geq 0}^3$ as
\begin{subequations}
\begin{align}
W_i^\delta(t) & \triangleq \sup_{t^\prime \in [0,t]}\ensuremath{\mathrm{e}}^{\delta t^\prime} \norm{\bm{w}_i(\cdot,t^\prime)}_{C^0([0,1];\ell^2(\mathbb{R}^2))}, && i \in \{1,2,3,4\}, \\
\bm{\beta}^\delta(t) & \triangleq \begin{bmatrix} \ensuremath{\mathrm{e}}^{\delta t}C_{f1}\bigl(\bm{X}_0(\cdot)\bigr)\\ \ensuremath{\mathrm{e}}^{\delta t}\norm{\bm{g}_0(\cdot)}_{C^0([0,1];\ell^2(\mathbb{R}^8))}, \\ \sup_{t^\prime \in[0,t]} \ensuremath{\mathrm{e}}^{\delta t^\prime} \norm{\bm{h}_0(t^\prime)}_{\ell^2(\mathbb{R}^8)} \end{bmatrix}.
\end{align}
\end{subequations}
using both bounds in~\eqref{eq:boundsg_ihi}, taking the supremum in~\eqref{eq:fadingEstimate}, and collecting the four resulting inequalities, provides
\begin{align}\label{eq:EqEdelta} 
\bigl( \mathbf{I}_4- (1+\epsilon) \mathbf{\Theta}_w \bigr) \bm{W}^\delta(t) \leq \mathbf{A}(\varrho)\bm{W}_0 + (1+\epsilon) \mathbf{B}_w \bm{\beta}^\delta(t), \quad t\in[0,T], \end{align}
where, to alleviate the notation, the following matrices $\mathbf{\Theta}_w \in \mathbf{M}_4(\mathbb{R}_{\geq 0})$ and $\mathbf{B}_w \in \mathbf{M}_{4\times 3}(\mathbb{R}_{\geq 0})$ have been defined:
\begin{subequations} 
\begin{align} 
\mathbf{\Theta}_{w} &\triangleq \mathbf{\Theta} \bigl( \bm{\phi}_f(\overline{\bm{w}}), \bm{\eta}, \overline{\bm{w}} \bigr), \\ 
\mathbf{B}_{w} &\triangleq \mathbf{B} \bigl( \bm{\phi}_f(\overline{\bm{w}}), \bm{\eta}, \overline{\bm{w}} \bigr). 
\end{align} 
\end{subequations}
By virtue of Eq.~\eqref{eq:SpectralRadius}, $\rho(\mathbf{\Theta}_{w})<1$, and, since the spectral radius is continuous, there exists $\epsilon_0\in \mathbb{R}_{>0}$ such that $\rho( (1+\epsilon)\mathbf{\Theta}_{w} )<1$ for all $\epsilon \in (0,\epsilon_0]$. In particular, the matrix-valued function $\mathbf{R}_w \in C^0([0,\epsilon_0];\mathbf{M}_4(\mathbb{R}_{\geq 0}))$, reading 
\begin{align} \mathbf{R}_w(\epsilon) \triangleq \bigl( \mathbf{I}_4- (1+\epsilon)\mathbf{\Theta}_{w} \bigr)^{-1} = \sum_{k=0}^\infty (1+\epsilon)^k \mathbf{\Theta}_{w}^k, 
\end{align} 
is well-defined and componentwise nonnegative. Thus, premultiplying Eq.~\eqref{eq:EqEdelta} by $\mathbf{R}_w(\epsilon)$, then multiplying by $\ensuremath{\mathrm{e}}^{-\delta t}$, and recalling Eq.~\eqref{eq:W0Betas} yields 
\begin{align}\label{eq:DwWW_dina} 
\bm{W}(t) \leq \mathbf{R}_w(\epsilon) \Bigl[ \mathbf{A}(\varrho)\bm{W}_0\ensuremath{\mathrm{e}}^{-\delta t} + (1+\epsilon) \mathbf{B}_{w}\bm{\beta} \Bigr], \quad t\in[0,T], 
\end{align}
since $\ensuremath{\mathrm{e}}^{-\delta t}\bm{\beta}^\delta(t)\leq\bm{\beta}$ componentwise. It remains to show that $\varrho \in \mathbb{R}_{>0}$ and $\epsilon \in (0,\epsilon_0]$ may be selected so that $\bm{w}(\cdot,t) \in \overline{\mathcal{B}}_w$ for all times. To this end, the following function $\bm{\mathcal{F}} \in C^0(\mathbb{R}_{\geq 0}\times[0,\epsilon_0];\mathbb{R}^4)$ is conveniently introduced: 
\begin{align}\label{eq:strictMarginMap} 
\bm{\mathcal{F}}(\varrho,\epsilon) \triangleq \overline{\bm{w}} - \mathbf{R}_w(\epsilon)\bigl[ \mathbf{A}(\varrho)\bm{W}_0 + (1+\epsilon) \mathbf{B}_{w}\bm{\beta} \bigr]. 
\end{align} 
From Eq.~\eqref{eq:condInitiDHDD}, it follows that 
\begin{align} 
